mapper.select:
select order_id, order_no, username, biz_type, biz_id, biz_ref, product_name, amount, pay_type,
       status, trade_no, pay_url, qrcode_url, client_ip, notify_time, pay_time, create_time, update_time, remark
from edu_pay_order

    username = #{username}
    and status = #{status}
    and biz_type = #{bizType}

        and (
            product_name ilike ('%' || #{keyword} || '%')
            or order_no ilike ('%' || #{keyword} || '%')
        )


order by create_time desc, order_id desc

select order_id, order_no, username, biz_type, biz_id, biz_ref, product_name, amount, pay_type,
       status, trade_no, pay_url, qrcode_url, client_ip, notify_time, pay_time, create_time, update_time, remark
from edu_pay_order
where username = #{username}
  and biz_type = #{bizType}
  and biz_id = #{bizId}
  and status = 'pending'
  and coalesce(biz_ref, '') = coalesce(#{bizRef}, '')
order by create_time desc, order_id desc
limit 1
